\begin{aligned}
&\text{Commutative:} && a + b = b + a, \quad a \cdot b = b \cdot a \\
&\text{Associative:} && (a + b) + c = a + (b + c), \quad (ab)c = a(bc) \\
&\text{Distributive:} && a(b + c) = ab + ac
\end{aligned}

\begin{aligned}
[a, b] &= \{x \in \mathbb{R} \mid a \le x \le b\} && \text{closed} \\
(a, b) &= \{x \in \mathbb{R} \mid a < x < b\} && \text{open} \\
[a, b) &= \{x \in \mathbb{R} \mid a \le x < b\} && \text{half-open} \\
[a, \infty) &= \{x \in \mathbb{R} \mid x \ge a\}
\end{aligned}
